with flattened_attrs as (select id, effective_from, tier_limits, tier_prices, array_min(tier_prices) as lowest_price, aggregate(tier_prices, cast(0 as double), (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, slice(tier_limits, 1, 2) as first_two_limits from price_tiers where effective_from < '2025-09-01') select *, lead(lowest_price, 2) over w_ordered as next_lowest_price, sum(lowest_price) over w_hist as cumulative_lowest_price, first_value(avg_tier_price, true) over w_hist as first_known_avg_tier_price, row_number() over (order by effective_from, id) as event_seq, avg(lowest_price) over (order by lowest_price, id rows between 6 preceding and current row) as lowest_price_avg_6 from flattened_attrs window w_ordered as (order by avg_tier_price, id), w_hist as (order by avg_tier_price, id rows between unbounded preceding and current row)
